INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT138-S3-Q11$batch10$, 138, 3, 11, $batch10$Main Conclusion$batch10$, $batch10$Counselor: Many people assume that personal conflicts are inevitable, but that assumption is just not so. Personal conflicts arise primarily because people are being irrational. For instance, people often find it easier to ascribe bad qualities to a person than good ones—even when there is more evidence of the latter. If someone suspects that a friend is unreliable, for example, a single instance may turn this suspicion into a feeling of certainty, whereas a belief that someone is reliable is normally built up only after many years of personal interaction.$batch10$, $batch10$Which one of the following most accurately expresses the main conclusion drawn in the argument?$batch10$, $batch10$D$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=138 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$Many people assume that personal conflicts are inevitable.$batch10$, $batch10$Opposing Point$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$Even when there is more evidence of good qualities than of bad ones, people find it easier to ascribe bad qualities than good ones.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$It is irrational to allow a single instance to turn one’s suspicion that a friend is unreliable into a feeling of certainty.$batch10$, $batch10$Not Stated$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$Personal conflicts are not inevitable.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$Unlike a suspicion that a friend is unreliable, a belief that someone is reliable is normally built up only after many years of personal interaction.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Many people assume personal conflicts are inevitable.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$That assumption is not so: personal conflicts are not inevitable.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Personal conflicts arise mainly from irrationality. For example, people find it easier to assign someone bad qualities than good ones, even against the evidence.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$The first sentence turns with "but that assumption is just not so," and that is the conclusion. Swap "that assumption" for its content and you get "personal conflicts are not inevitable." The rest explains why, with an example.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Personal conflicts are not inevitable.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the assumption the counselor rejects.$batch10$), ($batch10$B$batch10$, $batch10$This is the example of irrationality that supports the conclusion.$batch10$), ($batch10$C$batch10$, $batch10$The counselor describes this habit as an example. Calling it irrational in these words isn't the point being argued.$batch10$), ($batch10$D$batch10$, $batch10$With "that assumption" replaced, the counselor's claim is that personal conflicts are not inevitable.$batch10$), ($batch10$E$batch10$, $batch10$This is the last part of the example, which supports the claim about irrationality.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT138-S3-Q11$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
